// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MultiplicatorX4 c;

    function setUp() public { c = new MultiplicatorX4(); }

    function testFuzz_property(uint256 amount, bytes memory data) public {
        vm.assume(amount <= VALUE_CAP);
        Recorder rec = new Recorder();
        address owner = address(this); // test contract is msg.sender of setUp, hence Owner

        vm.deal(owner, amount);
        vm.prank(owner);
        c.Command{value: amount}(address(rec), data);

        // Rule: the reference forwards the command to adr exactly once for EVERY
        // (amount, data); the mutant never makes the call, so rec sees zero calls.
        assertTrue(rec.calls() == 1);
    }
}

contract Recorder {
    uint256 public calls;

    fallback() external payable {
        calls = calls + 1;
    }

    receive() external payable {
        calls = calls + 1;
    }
}
